cd /app && python3 - <<'PY'
import random
from feal import f_function
# enumerate high-bit toggles per byte
for mask in range(16):
    d=0
    for i in range(4):
        if mask>>i & 1: d|=0x80<<(8*i)
    vals=set()
    for _ in range(20000):
        x=random.getrandbits(32)
        vals.add(f_function(x)^f_function(x^d))
        if len(vals)>1: break
    if len(vals)==1:
        print(hex(d),hex(next(iter(vals))))
